import { ProductRepository } from "../domain/product-repository";
import { StockLevelDto } from "./order-dto";

export class ListStockLevelsUseCase {
  constructor(private readonly products: ProductRepository) {}

  async execute(): Promise<StockLevelDto[]> {
    const all = await this.products.findAll();
    return all.map((product) => ({
      productId: product.id,
      name: product.name,
      onHand: product.onHandQuantity,
      reserved: product.reservedQuantity,
      available: product.available,
    }));
  }
}

